  "inlineSchema": "// Prisma Schema for RevenueAI\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Organization {\n  id            String   @id @default(uuid())\n  name          String\n  businessType  String\n  monthlyTarget Float    @default(1500000.0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  users             User[]\n  customers         Customer[]\n  products          Product[]\n  transactions      Transaction[]\n  revenueLeaks      RevenueLeak[]\n  forecasts         Forecast[]\n  churnPredictions  ChurnPrediction[]\n  aiRecommendations AIRecommendation[]\n  notifications     Notification[]\n  revenueTargets    RevenueTarget[]\n  auditLogs         AuditLog[]\n}\n\nmodel User {\n  id             String       @id @default(uuid())\n  email          String       @unique\n  password       String\n  name           String\n  role           String       @default(\"OWNER\") // \"OWNER\" | \"MANAGER\" | \"STAFF\"\n  organizationId String\n  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime     @updatedAt\n\n  auditLogs AuditLog[]\n\n  @@index([organizationId])\n}\n\nmodel Customer {\n  id               String       @id @default(uuid())\n  organizationId   String\n  organization     Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  name             String\n  email            String\n  phone            String?\n  location         String?\n  customerSince    DateTime     @default(now())\n  totalRevenue     Float        @default(0.0)\n  lastPurchaseDate DateTime?\n  status           String       @default(\"NEW\") // \"ACTIVE\" | \"AT_RISK\" | \"CHURNED\" | \"VIP\" | \"NEW\"\n  createdAt        DateTime     @default(now())\n  updatedAt        DateTime     @updatedAt\n\n  transactions     Transaction[]\n  churnPredictions ChurnPrediction[]\n\n  @@index([organizationId])\n}\n\nmodel Product {\n  id             String       @id @default(uuid())\n  organizationId String\n  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  name           String\n  category       String\n  description    String?\n  price          Float\n  cost           Float\n  stock          Int          @default(0)\n  active         Boolean      @default(true)\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime     @updatedAt\n\n  transactions Transaction[]\n\n  @@index([organizationId])\n}\n\nmodel Transaction {\n  id              String       @id @default(uuid())\n  organizationId  String\n  organization    Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  customerId      String\n  customer        Customer     @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  productId       String\n  product         Product      @relation(fields: [productId], references: [id], onDelete: Cascade)\n  salespersonId   String?\n  quantity        Int\n  unitPrice       Float\n  grossAmount     Float\n  discount        Float        @default(0.0) // Percentage or amount\n  tax             Float        @default(0.0)\n  refundAmount    Float        @default(0.0)\n  netRevenue      Float\n  costAmount      Float\n  grossProfit     Float\n  profitMargin    Float\n  paymentStatus   String       @default(\"PAID\") // \"PAID\" | \"PENDING\" | \"FAILED\" | \"REFUNDED\" | \"PARTIALLY_REFUNDED\"\n  paymentMethod   String       @default(\"CARD\") // \"CASH\" | \"CARD\" | \"UPI\" | \"BANK_TRANSFER\" | \"OTHER\"\n  transactionDate DateTime     @default(now())\n  createdAt       DateTime     @default(now())\n  updatedAt       DateTime     @updatedAt\n\n  revenueLeaks RevenueLeak[]\n\n  @@index([organizationId])\n  @@index([customerId])\n  @@index([productId])\n  @@index([transactionDate])\n}\n\nmodel RevenueLeak {\n  id             String       @id @default(uuid())\n  organizationId String\n  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  transactionId  String?\n  transaction    Transaction? @relation(fields: [transactionId], references: [id], onDelete: SetNull)\n  type           String // e.g. \"EXCESSIVE_DISCOUNT\", \"FAILED_PAYMENT\", \"PRICING_ANOMALY\"\n  amount         Float\n  severity       String       @default(\"MEDIUM\") // \"LOW\" | \"MEDIUM\" | \"HIGH\" | \"CRITICAL\"\n  description    String\n  status         String       @default(\"OPEN\") // \"OPEN\" | \"RESOLVED\"\n  detectedDate   DateTime     @default(now())\n  createdAt      DateTime     @default(now())\n\n  @@index([organizationId])\n}\n\nmodel Forecast {\n  id               String       @id @default(uuid())\n  organizationId   String\n  organization     Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  periodDate       DateTime\n  predictedRevenue Float\n  lowerBound       Float\n  upperBound       Float\n  confidence       Float        @default(0.95)\n  modelVersion     String       @default(\"v1.0\")\n  createdAt        DateTime     @default(now())\n\n  @@index([organizationId])\n}\n\nmodel ChurnPrediction {\n  id               String       @id @default(uuid())\n  organizationId   String\n  organization     Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  customerId       String\n  customer         Customer     @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  churnProbability Float\n  riskLevel        String       @default(\"MEDIUM\") // \"LOW\" | \"MEDIUM\" | \"HIGH\"\n  keyFactors       String // JSON string array of reasons\n  predictedDate    DateTime     @default(now())\n\n  @@index([organizationId])\n  @@index([customerId])\n}\n\nmodel AIRecommendation {\n  id              String       @id @default(uuid())\n  organizationId  String\n  organization    Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  title           String\n  explanation     String\n  priority        String       @default(\"MEDIUM\") // \"LOW\" | \"MEDIUM\" | \"HIGH\"\n  potentialImpact Float?\n  category        String // \"DISCOUNT\", \"CHURN\", \"PRICING\", \"TARGET\"\n  status          String       @default(\"ACTIVE\") // \"ACTIVE\" | \"APPLIED\" | \"DISMISSED\"\n  createdAt       DateTime     @default(now())\n\n  @@index([organizationId])\n}\n\nmodel Notification {\n  id             String       @id @default(uuid())\n  organizationId String\n  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  title          String\n  message        String\n  type           String // \"LEAKAGE\", \"CHURN\", \"FORECAST\", \"SYSTEM\"\n  isRead         Boolean      @default(false)\n  createdAt      DateTime     @default(now())\n\n  @@index([organizationId])\n}\n\nmodel RevenueTarget {\n  id                 String       @id @default(uuid())\n  organizationId     String\n  organization       Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  year               Int\n  month              Int\n  targetAmount       Float\n  currentAmount      Float        @default(0.0)\n  achievementPercent Float        @default(0.0)\n  createdAt          DateTime     @default(now())\n  updatedAt          DateTime     @updatedAt\n\n  @@unique([organizationId, year, month])\n  @@index([organizationId])\n}\n\nmodel AuditLog {\n  id             String       @id @default(uuid())\n  organizationId String\n  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  userId         String\n  user           User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  action         String\n  entity         String\n  entityId       String?\n  details        String?\n  createdAt      DateTime     @default(now())\n\n  @@index([organizationId])\n}\n",
